using WAID.Application.Services;using WAID.Infrastructure.Persistence;namespace WAID.Infrastructure.Tests;public sealed class RepairRecommendationPersistenceTests{[Fact]public async Task Ranking_round_trip_preserves_decisions_factors_and_feedback(){var path=Path.Combine(Path.GetTempPath(),$"waid-rank-{Guid.NewGuid():N}.db");try{var db=new WaidDatabase($"Data Source={path};Pooling=False");await db.InitializeAsync(CancellationToken.None);var factors=new RepairRankingFactors(80,90,10,10,3,0,0,0,0,4,91);var item=new PrioritizedRepair("waid.dism","DISM",1,91,WAID.Domain.Repairs.SafetyLevel.High,true,false,true,90,80){RankingFactors=factors,AutoSelectable=false};var decision=new RepairRecommendationDecision("waid.dism",RepairCandidateStatus.Eligible,"eligible",factors,false,[],[]);var feedback=new Dictionary<string,RepairFeedbackAggregate>{{"waid.dism",new("waid.dism",4,1,0)}};var run=new RepairRankingRun(Guid.NewGuid(),DateTimeOffset.UtcNow,"v2",[item],[decision],feedback);var repo=new SqliteRepairRecommendationRepository(db);await repo.SaveAsync(run,CancellationToken.None);var loaded=await repo.GetLatestAsync(CancellationToken.None);Assert.Equal(91,loaded!.Ranked[0].RankingFactors!.FinalScore);Assert.False(loaded.Ranked[0].AutoSelectable);Assert.Equal(4,loaded.Feedback["waid.dism"].Successes);}finally{Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();if(File.Exists(path))File.Delete(path);}}}